package cli

import (
	"fmt"
	"os"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
	"github.com/spf13/cobra"
)

func decisionsCmd() *cobra.Command {
	cmd := &cobra.Command{
		Use:   "decisions",
		Short: "View and manage decisions for a feature",
	}

	cmd.AddCommand(decisionsListCmd())
	cmd.AddCommand(decisionsAckCmd())

	return cmd
}

func decisionsListCmd() *cobra.Command {
	var branch string
	var mine bool
	var all bool

	cmd := &cobra.Command{
		Use:   "show [feature]",
		Short: "List decisions for a feature (unread by default, auto-detects feature if omitted)",
		Args:  cobra.MaximumNArgs(1),
		ValidArgsFunction: func(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
			if len(args) == 0 {
				return internal.ListFeatures(), cobra.ShellCompDirectiveNoFileComp
			}
			return nil, cobra.ShellCompDirectiveNoFileComp
		},
		Run: func(cmd *cobra.Command, args []string) {
			var feature, featurePath string
			if len(args) > 0 {
				feature = args[0]
				featurePath = internal.FeaturePath(feature)
			} else {
				feature, featurePath = internal.DetectFeatureFromCwd()
				if feature == "" {
					fmt.Println("Could not detect feature from current directory.")
					fmt.Println("Usage: tws decisions show <feature> or run from inside a worktree.")
					os.Exit(1)
				}
			}

			decisions, err := internal.LoadDecisions(featurePath)
			if err != nil {
				fmt.Printf("No decisions found for feature: %s\n", feature)
				return
			}

			if len(decisions.Entries) == 0 {
				fmt.Println("No decisions recorded yet.")
				return
			}

			// Auto-detect current branch for --mine and unread filtering
			myBranch := ""
			if b, err := currentBranch(); err == nil {
				myBranch = b
			}

			lastRead := 0
			if !all && myBranch != "" {
				lastRead = internal.LastReadID(featurePath, myBranch)
			}

			count := 0
			for _, entry := range decisions.Entries {
				if branch != "" && entry.Branch != branch {
					continue
				}
				if mine && myBranch != "" && !entry.IsRelevantTo(myBranch) {
					continue
				}
				if !all && myBranch != "" && entry.ID <= lastRead {
					continue
				}
				fmt.Println(entry)
				count++
			}

			if count == 0 {
				if all {
					fmt.Println("No decisions match filters.")
				} else {
					fmt.Println("No unread decisions. Use --all to see everything.")
				}
			}
		},
	}

	cmd.Flags().StringVar(&branch, "branch", "", "Filter by source branch")
	cmd.Flags().BoolVar(&mine, "mine", false, "Show only decisions relevant to current branch")
	cmd.Flags().BoolVar(&all, "all", false, "Show all decisions (including already read)")

	return cmd
}

func decisionsAckCmd() *cobra.Command {
	return &cobra.Command{
		Use:   "ack [feature]",
		Short: "Mark all decisions as read for current branch",
		Args:  cobra.MaximumNArgs(1),
		ValidArgsFunction: func(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
			if len(args) == 0 {
				return internal.ListFeatures(), cobra.ShellCompDirectiveNoFileComp
			}
			return nil, cobra.ShellCompDirectiveNoFileComp
		},
		Run: func(cmd *cobra.Command, args []string) {
			var featurePath string
			if len(args) > 0 {
				featurePath = internal.FeaturePath(args[0])
			} else {
				_, featurePath = internal.DetectFeatureFromCwd()
				if featurePath == "" {
					fmt.Println("Could not detect feature. Usage: tws decisions ack <feature>")
					os.Exit(1)
				}
			}

			branch, err := currentBranch()
			if err != nil {
				fmt.Println("Error: could not detect current branch")
				os.Exit(1)
			}

			if err := internal.AckDecisions(featurePath, branch); err != nil {
				fmt.Printf("Error: %v\n", err)
				os.Exit(1)
			}

			fmt.Printf("Marked all decisions as read for branch: %s\n", branch)
		},
	}
}

package cli

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
	"github.com/spf13/cobra"
)

func hooksCmd() *cobra.Command {
	cmd := &cobra.Command{
		Use:   "hooks",
		Short: "Manage agent hooks for auto-read decisions",
	}

	cmd.AddCommand(hooksInstallCmd())
	cmd.AddCommand(hooksRemoveCmd())

	return cmd
}

// Claude Code settings.json hook structure
type claudeSettings struct {
	Hooks map[string][]hookMatcher `json:"hooks,omitempty"`
}

type hookMatcher struct {
	Matcher string       `json:"matcher"`
	Hooks   []hookAction `json:"hooks"`
}

type hookAction struct {
	Type    string `json:"type"`
	Command string `json:"command"`
	Timeout int    `json:"timeout,omitempty"`
}

func hooksInstallCmd() *cobra.Command {
	return &cobra.Command{
		Use:   "install [feature]",
		Short: "Install Claude Code hooks for auto-reading decisions",
		Long: `Install hooks into .claude/settings.local.json so that Claude Code
automatically checks for new decisions on session start and resume.

Optionally watches decisions.yaml for real-time notifications via FileChanged hook.

Run from inside a worktree, or specify the feature name.`,
		Args: cobra.MaximumNArgs(1),
		Run: func(cmd *cobra.Command, args []string) {
			var feature string
			if len(args) > 0 {
				feature = args[0]
			} else {
				feature, _ = internal.DetectFeatureFromCwd()
				if feature == "" {
					fmt.Println("Could not detect feature. Run from inside a worktree or specify: tws hooks install <feature>")
					os.Exit(1)
				}
			}

			featurePath := internal.FeaturePath(feature)
			stack, _ := internal.LoadStack(featurePath)

			installed := 0
			for _, entry := range stack.Branches {
				wtPath := internal.WorktreePath(feature, entry.Name)
				if _, err := os.Stat(wtPath); os.IsNotExist(err) {
					continue // archived
				}

				if err := installHooksForWorktree(wtPath, feature); err != nil {
					fmt.Printf("  [x] %s: %v\n", entry.Name, err)
				} else {
					fmt.Printf("  [+] %s: hooks installed\n", entry.Name)
					installed++
				}
			}

			if installed > 0 {
				fmt.Printf("Installed hooks in %d worktree(s)\n", installed)
				fmt.Println("Claude Code will now check for decisions on session start/resume.")
			}
		},
	}
}

func hooksRemoveCmd() *cobra.Command {
	return &cobra.Command{
		Use:   "remove [feature]",
		Short: "Remove auto-read decision hooks",
		Args:  cobra.MaximumNArgs(1),
		Run: func(cmd *cobra.Command, args []string) {
			var feature string
			if len(args) > 0 {
				feature = args[0]
			} else {
				feature, _ = internal.DetectFeatureFromCwd()
				if feature == "" {
					fmt.Println("Could not detect feature.")
					os.Exit(1)
				}
			}

			featurePath := internal.FeaturePath(feature)
			stack, _ := internal.LoadStack(featurePath)

			for _, entry := range stack.Branches {
				wtPath := internal.WorktreePath(feature, entry.Name)
				settingsPath := filepath.Join(wtPath, ".claude", "settings.local.json")
				if err := os.Remove(settingsPath); err == nil {
					fmt.Printf("  [-] %s: hooks removed\n", entry.Name)
				}
			}
		},
	}
}

func installHooksForWorktree(wtPath, feature string) error {
	settingsDir := filepath.Join(wtPath, ".claude")
	if err := os.MkdirAll(settingsDir, 0755); err != nil {
		return err
	}

	settingsPath := filepath.Join(settingsDir, "settings.local.json")

	// Build the decisions check command
	showCmd := fmt.Sprintf("tws decisions show %s --mine 2>/dev/null || true", feature)
	ackHint := fmt.Sprintf("echo 'To acknowledge: tws decisions ack %s'", feature)
	fullCmd := showCmd + " && " + ackHint

	settings := claudeSettings{
		Hooks: map[string][]hookMatcher{
			"SessionStart": {
				{
					Matcher: "startup",
					Hooks: []hookAction{
						{Type: "command", Command: fullCmd, Timeout: 10},
					},
				},
				{
					Matcher: "resume",
					Hooks: []hookAction{
						{Type: "command", Command: showCmd, Timeout: 10},
					},
				},
			},
		},
	}

	data, err := json.MarshalIndent(settings, "", "  ")
	if err != nil {
		return err
	}

	return os.WriteFile(settingsPath, data, 0644)
}

package internal

import (
	"os"
	"path/filepath"
	"strings"
)

const workspaceMarker = ".tws-workspace"

// DetectWorkspaceRoot checks if cwd is inside an existing workspace.
// Returns the workspace root or empty string.
func DetectWorkspaceRoot(cwd string, cfg Config) string {
	// Tier 1: Walk up looking for .tws-workspace marker
	dir := cwd
	for {
		if _, err := os.Stat(filepath.Join(dir, workspaceMarker)); err == nil {
			return dir
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			break
		}
		dir = parent
	}

	// Tier 2: Check if cwd is inside any configured workspace path
	for _, ws := range cfg.Workspaces {
		absWs, err := filepath.Abs(ws)
		if err != nil {
			continue
		}
		absCwd, err := filepath.Abs(cwd)
		if err != nil {
			continue
		}
		if strings.HasPrefix(absCwd, absWs+string(filepath.Separator)) || absCwd == absWs {
			return absWs
		}
	}

	// Tier 3: Check if cwd is inside ~/tws
	home, _ := os.UserHomeDir()
	globalDefault := filepath.Join(home, "tws")
	absCwd, _ := filepath.Abs(cwd)
	if strings.HasPrefix(absCwd, globalDefault+string(filepath.Separator)) || absCwd == globalDefault {
		return globalDefault
	}

	return ""
}

// resolveTwsRoot contains the resolution logic with injectable dependencies.
func resolveTwsRoot(envRoot string, cwd string, repoRoot string, repoErr error, cfg Config) string {
	// 0. TWS_ROOT env var — always wins
	if envRoot != "" {
		return envRoot
	}

	// 1. Already inside a workspace? Return that root.
	if wsRoot := DetectWorkspaceRoot(cwd, cfg); wsRoot != "" {
		return wsRoot
	}

	// 2. Global config keyed by repo path
	if repoErr == nil {
		if ws, ok := cfg.Workspaces[repoRoot]; ok {
			return ws
		}

		// 3. Repo-relative sibling: ../<repo-name>.tws/
		repoName := filepath.Base(repoRoot)
		return filepath.Join(filepath.Dir(repoRoot), repoName+".tws")
	}

	// 4. Global fallback
	home, _ := os.UserHomeDir()
	return filepath.Join(home, "tws")
}

func TwsRoot() string {
	repoRoot, repoErr := MainRepoRoot()
	cfg := LoadConfig()
	cwd, _ := os.Getwd()
	return resolveTwsRoot(os.Getenv("TWS_ROOT"), cwd, repoRoot, repoErr, cfg)
}

func FeaturePath(feature string) string {
	return filepath.Join(TwsRoot(), feature)
}

func WorktreePath(feature, branch string) string {
	return filepath.Join(FeaturePath(feature), "worktrees", branch)
}

// DetectFeatureFromCwd detects the current feature name from the working directory.
// Works when cwd is inside a worktree: <workspace>/<feature>/worktrees/<branch>/
// Returns feature name and feature path, or empty strings if not detected.
func DetectFeatureFromCwd() (string, string) {
	cwd, err := os.Getwd()
	if err != nil {
		return "", ""
	}

	wsRoot := TwsRoot()
	absWs, _ := filepath.Abs(wsRoot)
	absCwd, _ := filepath.Abs(cwd)

	// Check if cwd is inside the workspace
	if !strings.HasPrefix(absCwd, absWs+string(filepath.Separator)) {
		return "", ""
	}

	// Get the relative path from workspace root
	rel, err := filepath.Rel(absWs, absCwd)
	if err != nil {
		return "", ""
	}

	// First component is the feature name
	parts := strings.SplitN(rel, string(filepath.Separator), 2)
	if len(parts) == 0 {
		return "", ""
	}

	feature := parts[0]
	featurePath := filepath.Join(absWs, feature)

	// Verify it's actually a feature dir (has stack.yaml or worktrees/)
	if _, err := os.Stat(filepath.Join(featurePath, "worktrees")); err == nil {
		return feature, featurePath
	}
	if _, err := os.Stat(filepath.Join(featurePath, "stack.yaml")); err == nil {
		return feature, featurePath
	}

	return "", ""
}

// ListFeatures returns the names of all feature directories in the workspace.
func ListFeatures() []string {
	wsRoot := TwsRoot()
	entries, err := os.ReadDir(wsRoot)
	if err != nil {
		return nil
	}
	var features []string
	for _, e := range entries {
		if e.IsDir() && e.Name() != ".tws-workspace" {
			features = append(features, e.Name())
		}
	}
	return features
}

// ListBranches returns the branch names for a feature from stack.yaml,
// or from the worktrees directory if no stack exists.
func ListBranches(feature string) []string {
	featurePath := FeaturePath(feature)
	stack, err := LoadStack(featurePath)
	if err == nil && len(stack.Branches) > 0 {
		var names []string
		for _, e := range stack.Branches {
			names = append(names, e.Name)
		}
		return names
	}

	// Fallback: list worktree directories
	wtDir := filepath.Join(featurePath, "worktrees")
	entries, err := os.ReadDir(wtDir)
	if err != nil {
		return nil
	}
	var names []string
	for _, e := range entries {
		if e.IsDir() {
			names = append(names, e.Name())
		}
	}
	return names
}
